def sha(raw):return hashlib.sha256(raw).hexdigest()

def read(root,name,expected):
    raw=(root/name).read_bytes();require(sha(raw)==expected or semantic_valid(name,raw),'Source bytes changed: '+name);return raw

def semantic_valid(name,raw):
    lock=next((m.get('semanticSha256') for m in METADATA if m['filename']==name),None)
    if not lock:return False
    def normalize(x):
        if isinstance(x,dict):return {k:normalize(v) for k,v in x.items() if k not in ['ID','CreatedOn','LinkedLocation','lastViewed']}
        if isinstance(x,list):return [normalize(v) for v in x]
        return x
    x=json.loads(raw);x=json.loads(x) if isinstance(x,str) else x
    if name=='general-health-indicators.json':x=[{'indicator':normalize(json.loads(k)),'subIndicators':normalize(v)} for k,v in x.items()]
    else:x=normalize(x)
    return sha(json.dumps(x,sort_keys=True,ensure_ascii=False).encode())==lock

def http(url,fields=None):
    headers={'User-Agent':'NHHR public source verification'}
    data=None
    if fields is not None:data=urlencode(fields,doseq=True).encode();headers['Content-Type']='application/x-www-form-urlencoded; charset=UTF-8'
    with urlopen(Request(url,data=data,headers=headers),timeout=60) as response:return response.read()

def decode(raw):
    return raw.decode('utf-16-le').lstrip('\ufeff') if b'\0' in raw[:100] else raw.decode('utf-8-sig')

