def number(raw):
    if raw=='-':return None,'Not released (source dash; reason not specified)'
    require(re.fullmatch(r'\d+(?:\.\d+)?',raw) is not None,'Unreviewed source value/marker')
    n=Decimal(raw);require(n.is_finite() and n>=0,'Invalid source rate');return float(n),'Reported'

