def make_row(receipt,geometry,name,original,value,literal,status,rendition,source_label,definition):
    props=geometry[receipt['code']]['properties']
    profile_slug=receipt['name'].replace('/','_')
    return {'chsa_name':receipt['name'],'chsa_code':receipt['code'],'rate_per_1000':value,'indicator':name,'period':period(original),'original_period':original,'sex':'Total','reporting_status':status,'source_raw':literal,'source_indicator':source_label,'source_record_kind':rendition,'jurisdiction_name':receipt['name']+' CHSA','source_unit':'Per 1000 population','standard_population':'2011 Canadian Census population','age_universe':re.search(r'\(([^)]+)\)$',name).group(1),'rate_definition':'Age-standardized lifetime prevalence' if ' lifetime prevalence rate ' in name else 'Age-standardized incidence','source_data_source':'BC Ministry of Health','source_url':BASE+'/CHSAHealthProfiles/CHSAHealthReport/'+quote(profile_slug,safe=''),'definition_url':definition['furtherInformation'],'source_attribution':ATTRIBUTION,'boundary_vintage':'2018','lha_code':props['LHA_CD'],'hsda_code':props['HSDA_CD'],'ha_code':props['HA_CD']}

def save(path,value,check):
    raw=(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n').encode()
    if check:require(path.exists() and path.read_bytes()==raw,'Prepared output differs: '+str(path.relative_to(ROOT)))
    else:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--input',required=True,type=Path);p.add_argument('--refresh',action='store_true');p.add_argument('--check',action='store_true');a=p.parse_args()
    if a.refresh:refresh(a.input)
    release,provenance,geo,index=prepare(a.input)
    for path in [ROOT/'src/atlas/snapshots/chsa-connections.json',ROOT/'public/data/nhhr/chsa-connections.json']:save(path,release,a.check)
    save(ROOT/'public/data/nhhr/chsa-connections-provenance.json',provenance,a.check);save(ROOT/'public/data/nhhr'/ASSET,geo,a.check);save(ROOT/'src/atlas/chsaBoundaryIndex.json',index,a.check);save(ROOT/'public/data/nhhr/chsa-boundary-index.json',index,a.check)
    print(('Verified' if a.check else 'Prepared')+' two supplementary CHSA views / 4,459 source rows / 40 archived polygons and 29 public source areas.')
if __name__=='__main__':main()
